```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input received on this call under `last-input`.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        // A transport failure is a value, not a trap: count it as zero characters.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars");
        let notified = notifier::notify(&message);

        // The ensures clause requires `notified == true` on every output. If the
        // notifier refuses, trap instead of emitting a report that violates it.
        if !notified {
            panic!("notifier refused the heartbeat");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

